function fixtureValue(seed: number, socket: number, stat: number): number {
  let value = (seed ^ (socket * 2654435761) ^ (stat * 2246822519)) >>> 0;
  value = Math.imul(value ^ (value >>> 16), 2246822507) >>> 0;
  return value % 4;
}

export const timelessSeedRecords: TimelessSeedRecord[] = [];
const timelessFixtureCatalog = [
  { jewelType: "Lethal Pride", conquerors: ["Kaom", "Rakiata", "Kiloava", "Akoya"], min: 10000, max: 18000, step: 37 },
  { jewelType: "Brutal Restraint", conquerors: ["Deshret", "Balbala", "Asenath", "Nasima"], min: 500, max: 8000, step: 37 },
  { jewelType: "Elegant Hubris", conquerors: ["Cadiro", "Victario", "Chitus", "Caspiro"], min: 2000, max: 160000, step: 733 },
  { jewelType: "Glorious Vanity", conquerors: ["Xibaqua", "Zerphi", "Ahuana", "Doryani"], min: 100, max: 8000, step: 37 },
  { jewelType: "Militant Faith", conquerors: ["Venarius", "Maxarius", "Dominus", "Avarius"], min: 2000, max: 10000, step: 37 }
] as const;

for (const catalogEntry of timelessFixtureCatalog) {
  const { jewelType, conquerors, min, max, step } = catalogEntry;
  for (const conqueror of conquerors) {
  for (const socketId of ["socket-1", "socket-2", "socket-3"]) {
    const socket = Number(socketId.at(-1));
    for (let seed = min; seed <= max; seed += step) {
      timelessSeedRecords.push({
        jewelType,
        conqueror,
        seed,
        socketId,
        stats: Object.fromEntries(timelessStatOptions.map((stat, index) => [
          stat.id,
          fixtureValue(seed, socket, index)
        ]))
      });
    }
  }
  }
}

